    private readonly record struct EffectiveNoGcRegionBudget(
        long TotalBytes,
        long LohBytes,
        long MemoryLoadBytes,
        long SystemMemoryLimitBytes,
        bool Capped)
    {
        public bool CanStart => TotalBytes >= MinimumNoGcRegionBudgetBytes;
    }

