        try
        {
            await resume.ConfigureAwait(false);
            return timeoutOnResume;
        }
        finally
        {
            lock (Gate)
            {
                _inSearchCollectionReachedForTesting = null;
                _inSearchCollectionResumeForTesting = null;
            }
        }
    }

